package com.ruoyi.paiflow.service;
import com.alibaba.fastjson2.*;
import com.ruoyi.paiflow.mapper.*;
import com.ruoyi.system.service.ISysUserService;
import com.ruoyi.framework.web.service.SysPermissionService;
import com.ruoyi.system.secret.ManagedSecretService;
import java.util.*;
import java.nio.charset.StandardCharsets;
import org.springframework.stereotype.Service;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import static com.ruoyi.paiflow.service.ModelOperationJson.error;
/** 固定工具版本与当前平台/成员/精确运维用途交集；公开描述不包含出口与私有材料。 */
@Service @ConditionalOnProperty(prefix="paiflow",name={"enabled","tools.enabled"},havingValue="true")
public class ToolRuntimeCatalog {
 public record Fixed(String resourceId,JSONObject descriptor,JSONObject configuration,long toolId,long versionId,long spaceId,long ownerUserId,String configurationHash) { @Override public String toString(){return "FixedTool[redacted]";} }
 private final ToolMapper tools;private final SpaceMapper spaces;private final ISysUserService users;private final SysPermissionService permissions;private final ToolRuntimeProperties properties;private final ManagedSecretService secrets;private final org.mybatis.spring.SqlSessionTemplate session;
 public ToolRuntimeCatalog(ToolMapper tools,SpaceMapper spaces,ISysUserService users,SysPermissionService permissions,ToolRuntimeProperties properties,ManagedSecretService secrets,org.mybatis.spring.SqlSessionTemplate session){this.tools=tools;this.spaces=spaces;this.users=users;this.permissions=permissions;this.properties=properties;this.secrets=secrets;this.session=session;}
 public Fixed bindCurrent(long space,String plugin,String version,String op,String app){session.clearCache();var tool=tools.byPlugin(plugin);if(tool==null || ToolService.number(tool,"spaceId")!=space || ToolService.number(tool,"enabled")!=1 || ToolService.number(tool,"temporary")!=0)throw error("工具不存在/停用或临时版本不可绑定",404);var row=tools.byVersion(ToolService.number(tool,"id"),version);if(row==null)throw error("原工具版本映射不存在",409);return fixed(tool,row,op,app);}
 public Fixed resolvePinned(long space,long owner,String resource,JSONObject descriptor){requireOwner(space,owner,false);var id=ids(resource);session.clearCache();var tool=tools.find(id[0]);var version=tools.fixed(id[1]);if(tool==null||version==null||ToolService.number(tool,"enabled")!=1||ToolService.number(tool,"temporary")!=0||ToolService.number(tool,"spaceId")!=space||ToolService.number(version,"toolId")!=id[0]||ToolService.number(version,"spaceId")!=space)throw error("固定工具已失效",409);String op=operationId(resource);var fixed=fixed(tool,version,op,descriptor==null?null:descriptor.getString("legacyAppId"));if(!ToolSchema.same(descriptor,fixed.descriptor()))throw error("工具固定描述或版本改变",409);profile(fixed,owner);return fixed;}
 private Fixed fixed(Map<String,Object> tool,Map<String,Object> version,String op,String app){String raw=(String)version.get("configurationJson");if(!Objects.equals(DataRuntimeCatalog.sha(raw),version.get("configurationHash")))throw error("工具版本hash不一致",409);var config=JSON.parseObject(raw);if(!Objects.equals(app,config.get("legacyAppId"))||!ToolSchema.operations(config.getJSONObject("openApiSchema")).containsKey(op))throw error("工具版本/operation/App兼容映射冲突",409);
  long id=ToolService.number(tool,"id"),vid=ToolService.number(version,"id");String resource="tool:"+id+":version:"+vid+":operation:"+Base64.getUrlEncoder().withoutPadding().encodeToString(op.getBytes(StandardCharsets.UTF_8));var descriptor=JSONObject.of("kind","tool","provider","spark-link","version",Long.toString(vid),"pluginId",tool.get("pluginId"),"operationId",op,"legacyVersion",version.get("legacyVersion"),"legacyAppId",app,"effectClass",config.get("effectClass"),"openApiSchema",ToolOpenApi.publicOperation(config.getJSONObject("openApiSchema"),op),"enabled",true);ToolSchema.guardApi(descriptor.getJSONObject("openApiSchema"));return new Fixed(resource,descriptor,config,id,vid,ToolService.number(tool,"spaceId"),ToolService.number(tool,"ownerUserId"),(String)version.get("configurationHash"));}
 public void requireOwner(long space,long owner,boolean write){session.clearCache();var user=users.selectUserById(owner);if(user==null||!"0".equals(user.getStatus())||!"0".equals(user.getDelFlag()))throw error("工具运行主体失效",403);var granted=permissions.getMenuPermission(user);String permission=write?"paiflow:tool:invoke":"paiflow:tool:query";if(granted==null||!(granted.contains("*:*:*")||granted.contains(permission)))throw error("工具平台权限撤销",403);var s=spaces.find(space);var member=spaces.member(space,owner);if(s==null||s.getDeleted()!=0||member==null||!"active".equals(member.getStatus())||member.getRole()==null||member.getRole()<1||member.getRole()>(write?2:3)||s.isDefaultPersonal()&&(!Objects.equals(s.getOwnerUserId(),owner)||s.getTeamId()!=null||member.getRole()!=1))throw error("工具空间权限失效",403);}
 public ToolRuntimeProperties.Profile profile(Fixed f,long actor){var matches=properties.getProfiles().stream().filter(p->p.isEnabled()&&p.getToolId()==f.toolId()&&Objects.equals(p.getConfigurationHash(),f.configurationHash())&&Objects.equals(p.getOperationId(),f.descriptor().get("operationId"))).toList();if(matches.size()!=1)throw error("工具准确版本用途尚未批准",503);var p=matches.getFirst();var op=ToolSchema.operations(f.configuration().getJSONObject("openApiSchema")).get(p.getOperationId());String endpoint=f.configuration().getJSONObject("openApiSchema").getJSONArray("servers").getJSONObject(0).getString("url")+op.path();
  if(!Objects.equals(p.getEndpoint(),endpoint)||!Objects.equals(p.getEffectClass(),f.descriptor().get("effectClass"))||!p.getAllowedUserIds().contains(actor)||!p.getAllowedSpaceIds().contains(f.spaceId())||p.getTimeoutSeconds()<1||p.getTimeoutSeconds()>1800||p.getMaxCalls()<1||p.getMaxCalls()>1000||p.getMaxRequestBytes()<1||p.getMaxRequestBytes()>2*1024*1024||p.getMaxResponseBytes()<1||p.getMaxResponseBytes()>2*1024*1024)throw error("工具用途主体/目标/预算未批准",403);
  requireOwner(f.spaceId(),actor,"write".equals(p.getEffectClass()));credentialVersion(f,p);return p;
 }
 String credentialVersion(Fixed f,ToolRuntimeProperties.Profile p){Object reference=f.configuration().get("credentialRef");if(reference==null){if(p.getCredentialRef()!=null||p.getSecretAlias()!=null)throw error("工具认证用途与固定版本冲突",409);if(ToolSchema.operations(f.configuration().getJSONObject("openApiSchema")).get(p.getOperationId()).schema().containsKey("security"))throw error("工具认证方案尚未配置",503);return "none";}
  if(!Objects.equals(reference,p.getCredentialRef())||p.getSecretAlias()==null||"apiKey".equals(ToolHttpAuthentication.mode(f.configuration()))&&(!Set.of("header","query").contains(p.getAuthenticationIn())||p.getAuthenticationName()==null||p.getAuthenticationName().isBlank()))throw error("工具认证注入用途尚未配置",503);var m=secrets.metadata("AI",p.getSecretAlias());if(!"ACTIVE".equals(m.status())||m.activeVersion()==null||!"paiflow".equals(m.projectCode())||!Objects.equals(p.getSecretProvider(),m.providerCode())||!Objects.equals(p.getSecretCapability(),m.capabilityCode())||!Objects.equals(p.getSecretAuthMode(),m.authMode()))throw error("工具托管凭据用途失效",503);return "managed:"+m.alias()+":"+m.activeVersion()+":"+m.rowVersion();}
 String material(Fixed f,ToolRuntimeProperties.Profile p,String version){if("none".equals(version))return null;if(!version.equals(credentialVersion(f,p)))throw error("工具凭据已轮换",409);var resolved=secrets.resolve("AI",p.getSecretAlias());var metadata=resolved.metadata();if(metadata==null||!version.equals("managed:"+metadata.alias()+":"+metadata.activeVersion()+":"+metadata.rowVersion()))throw error("工具读取的托管版本错配",409);if(!version.equals(credentialVersion(f,p)))throw error("工具读取凭据期间轮换",409);String value=resolved.value();if(value==null||value.isBlank()||value.chars().anyMatch(Character::isISOControl))throw error("工具私有材料无效",503);return value;}
 static long[] ids(String resource){try{if(resource==null||resource.length()>1024||!resource.matches("tool:[1-9][0-9]*:version:[1-9][0-9]*:operation:[A-Za-z0-9_-]+"))throw new IllegalArgumentException();String[] p=resource.split(":");operationId(resource);return new long[]{Long.parseLong(p[1]),Long.parseLong(p[3])};}catch(RuntimeException e){throw error("工具资源标识无效",409);}}
 static String operationId(String resource){try{String encoded=resource.substring(resource.lastIndexOf(':')+1);String op=new String(Base64.getUrlDecoder().decode(encoded),StandardCharsets.UTF_8);ToolSchema.text(op,128,"operationId");if(!encoded.equals(Base64.getUrlEncoder().withoutPadding().encodeToString(op.getBytes(StandardCharsets.UTF_8))))throw new IllegalArgumentException();return op;}catch(RuntimeException e){throw error("工具operation编码无效",409);}}
}
